document.addEventListener("DOMContentLoaded",()=>{var e=`../../scripts/data/${window.quizFilename||"eval_questions"}.json`;fetch(e).then(e=>e.json()).then(e=>{let{title:t,questions:d}=e,s=0,l=0;e=document.createElement("div");e.className="slide",e.innerHTML=`
        <h2>📊 Quiz: ${t}</h2>
        <div id="quiz-progress"><div id="quiz-progress-bar"></div></div>
        <div id="quiz-box"></div>
        `,document.querySelector("main").appendChild(e);let a=document.getElementById("quiz-box");!function n(i){var e=(i+1)/d.length*100;document.getElementById("quiz-progress-bar").style.width=e+"%";let r=d[i],o=(a.innerHTML=`
          <form id="quiz-form">
            <fieldset>
              <legend><strong>Q${i+1}:</strong> ${r.question}</legend>
              ${r.options.map((e,t)=>`
                <label>
                  <input type="radio" name="answer" value="${t}">
                  ${e}
                </label>
              `).join("")}
              <button type="submit" style="margin-top: 1rem;">Submit Answer</button>
            </fieldset>
          </form>
          <div id="feedback" style="margin-top: 1rem;"></div>
        `,a.innerHTML=`<p><strong>Question ${i+1} of ${d.length}</strong></p>`+a.innerHTML,document.getElementById("quiz-form"));o.addEventListener("submit",e=>{e.preventDefault();var e=o.querySelector("input[name='answer']:checked"),t=document.getElementById("feedback");e?((e=parseInt(e.value)===r.answer)&&l++,t.innerHTML=`
            <p><strong>${e?"✅ Correct!":"❌ Incorrect."}</strong></p>
            <p><em>${r.explanation}</em></p>
            <button id="next-btn" style="margin-top: 1rem;">${i+1<d.length?"Next Question":"See Results"}</button>
          `,o.querySelectorAll("input").forEach(e=>e.disabled=!0),document.getElementById("next-btn").addEventListener("click",()=>{++s<d.length?n(s):a.innerHTML=`
          <h3>🎉 Quiz Complete!</h3>
          <p><strong>Your Score:</strong> ${l} / ${d.length}</p>
        `})):t.innerHTML="<p>Please select an answer.</p>"})}(s)}).catch(e=>{console.error("Error loading quiz data:",e);e=document.createElement("div");e.className="slide",e.innerHTML="<h2>Quiz Error</h2><p>Unable to load quiz questions. Please check your JSON file path or syntax.</p>",document.querySelector("main").appendChild(e)})});